<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">classification_loss </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cross_entropy_classification(y_true_class, y_pred_class)</span></span>
